import{_ as o,a as t,b as l}from"./chunks/payload-3.Dh4aD50w.js";import{_ as r,o as i,c as e,a5 as s}from"./chunks/framework.CcrBcQWS.js";const p=JSON.parse('{"title":"Payload 설정","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/payload_setting.md","filePath":"ko/manual/troubleshooting/payload_setting.md","lastUpdated":1787021357000}'),n={name:"ko/manual/troubleshooting/payload_setting.md"};function d(g,a,u,_,m,c){return i(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="payload-설정" tabindex="-1">Payload 설정 <a class="header-anchor" href="#payload-설정" aria-label="Permalink to &quot;Payload 설정&quot;">​</a></h1><p>RBQGUI의 <strong>Payload Configuration</strong>에서 로봇에 장착된 추가 하중(페이로드)의 질량과 오프셋을 입력해 주행 안정성을 맞출 수 있습니다.</p><h2 id="사전-준비" tabindex="-1">사전 준비 <a class="header-anchor" href="#사전-준비" aria-label="Permalink to &quot;사전 준비&quot;">​</a></h2><ul><li>로봇을 평평하고 안전한 바닥에 둡니다.</li><li>RBQGUI가 로봇에 정상 연결되어 있어야 합니다.</li><li>장착된 장비의 무게 중심 위치(X/Y/Z 오프셋)를 미리 확인합니다.</li></ul><h2 id="설정-절차" tabindex="-1">설정 절차 <a class="header-anchor" href="#설정-절차" aria-label="Permalink to &quot;설정 절차&quot;">​</a></h2><ol><li>RBQGUI에서 <strong>Payload Configuration</strong> 화면을 엽니다.</li><li>상단 입력란에 아래 값을 입력합니다. <ul><li><strong>Mass (kg)</strong>: 추가 하중의 질량</li><li><strong>Offset X/Y/Z (m)</strong>: 로봇 기준 좌표계에서 하중 중심 위치</li></ul></li></ol><figure><img src="'+o+'" alt="Payload Configuration 입력 화면"></figure><ol start="3"><li><strong>+ Add</strong>를 눌러 입력값을 <strong>Added Payload</strong> 목록에 추가합니다.</li><li>값이 목록에 정상적으로 추가되었는지 확인한 뒤 <strong>Set Payload</strong>를 누릅니다.</li></ol><figure><img src="'+t+'" alt="Added Payload 목록에 값이 추가된 화면"></figure><ol start="5"><li>확인 팝업이 나오면 값(질량, 오프셋)을 다시 확인하고 <strong>Confirm</strong>을 눌러 로봇에 적용합니다.</li></ol><figure><img src="'+l+'" alt="Payload 적용 확인 팝업 화면"></figure><ol start="6"><li>적용 후 필요한 경우 <strong>Load Payload</strong>로 현재 적용값을 불러와 재확인합니다.</li></ol><h2 id="버튼-기능" tabindex="-1">버튼 기능 <a class="header-anchor" href="#버튼-기능" aria-label="Permalink to &quot;버튼 기능&quot;">​</a></h2><ul><li><strong>+ Add</strong>: 입력한 질량/오프셋 값을 후보 목록에 추가</li><li><strong>Clear</strong>: 입력 필드 값 초기화</li><li><strong>Set Payload</strong>: Added Payload의 값을 로봇에 적용</li><li><strong>Load Payload</strong>: 현재 로봇에 적용된 페이로드 값을 조회</li><li><strong>Reset Payload</strong>: 페이로드 값을 초기 상태로 되돌림</li></ul>',14)])])}const P=r(n,[["render",d]]);export{p as __pageData,P as default};
